// truth-mirror managed OMP hook
// Auto-generated by `truth-mirror install-hooks --omp`.
import { execFile } from "node:child_process";
import { promisify } from "node:util";

const run = promisify(execFile);
const globalArgs = [];

export default function truthMirror(pi) {
  let lastInjected = "";
  pi.on("context", async (event) => {
    let text = "";
    try {
      const { stdout } = await run("truth-mirror", [...globalArgs, "reinject", "--agent", "omp"], {
        cwd: process.cwd(),
      });
      text = (stdout || "").trim();
    } catch {
      return;
    }
    if (!text || text === lastInjected) return;
    lastInjected = text;
    return {
      messages: [
        ...event.messages,
        { role: "user", content: [{ type: "text", text }] },
      ],
    };
  });
}
